import { readFileSync } from 'node:fs';

const STATES = new Set(['pending', 'succeeded', 'failed']);

function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

function validate(spec) {
  if (!Array.isArray(spec)) {
    throw new Error('spec must be an array');
  }
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job)) {
      throw new Error('each job must be an object');
    }
    if (!isNonEmptyString(job.id)) {
      throw new Error('job id must be a nonempty string');
    }
    if (jobs.has(job.id)) {
      throw new Error(`duplicate job id: ${job.id}`);
    }
    if (!Array.isArray(job.deps)) {
      throw new Error(`job ${job.id} deps must be an array`);
    }
    const seenDeps = new Set();
    for (const dep of job.deps) {
      if (!isNonEmptyString(dep)) {
        throw new Error(`job ${job.id} has a malformed dependency`);
      }
      if (seenDeps.has(dep)) {
        throw new Error(`job ${job.id} has duplicate dependency: ${dep}`);
      }
      seenDeps.add(dep);
    }
    if (!STATES.has(job.state)) {
      throw new Error(`job ${job.id} has invalid state: ${job.state}`);
    }
    jobs.set(job.id, { id: job.id, deps: job.deps.slice(), state: job.state });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) {
        throw new Error(`job ${job.id} references unknown dependency: ${dep}`);
      }
    }
  }
  return jobs;
}

function topologicalOrder(jobs) {
  const indegree = new Map();
  const children = new Map();
  for (const id of jobs.keys()) {
    indegree.set(id, 0);
    children.set(id, []);
  }
  for (const job of jobs.values()) {
    indegree.set(job.id, job.deps.length);
    for (const dep of job.deps) {
      children.get(dep).push(job.id);
    }
  }
  const available = [];
  for (const [id, deg] of indegree) {
    if (deg === 0) available.push(id);
  }
  available.sort();
  const order = [];
  while (available.length > 0) {
    const id = available.shift();
    order.push(id);
    for (const child of children.get(id)) {
      const deg = indegree.get(child) - 1;
      indegree.set(child, deg);
      if (deg === 0) {
        const idx = lowerBound(available, child);
        available.splice(idx, 0, child);
      }
    }
  }
  if (order.length !== jobs.size) {
    throw new Error('dependency cycle detected');
  }
  return order;
}

function lowerBound(arr, value) {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] < value) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

function findFailedAncestors(id, jobs, cache) {
  if (cache.has(id)) return cache.get(id);
  const result = new Set();
  cache.set(id, result);
  const job = jobs.get(id);
  for (const dep of job.deps) {
    const depJob = jobs.get(dep);
    if (depJob.state === 'failed') {
      result.add(dep);
    }
    const depAncestors = findFailedAncestors(dep, jobs, cache);
    for (const a of depAncestors) result.add(a);
  }
  return result;
}

export function planJobs(spec) {
  const jobs = validate(spec);
  const order = topologicalOrder(jobs);

  const cache = new Map();
  const blocked = [];
  const blockedIds = new Set();
  for (const job of jobs.values()) {
    if (job.state !== 'pending') continue;
    const failedAncestors = findFailedAncestors(job.id, jobs, cache);
    if (failedAncestors.size > 0) {
      blockedIds.add(job.id);
      blocked.push({ id: job.id, causes: Array.from(failedAncestors).sort() });
    }
  }
  blocked.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));

  const finalOrder = order.filter(id => {
    const job = jobs.get(id);
    return job.state === 'pending' && !blockedIds.has(id);
  });

  const ready = [];
  for (const job of jobs.values()) {
    if (job.state !== 'pending' || blockedIds.has(job.id)) continue;
    if (job.deps.every(dep => jobs.get(dep).state === 'succeeded')) {
      ready.push(job.id);
    }
  }
  ready.sort();

  return { order: finalOrder, ready, blocked };
}

function main() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('usage: job-plan.js SPECFILE\n');
    process.exitCode = 2;
    return;
  }
  let text;
  try {
    text = readFileSync(args[0], 'utf8');
  } catch (err) {
    process.stderr.write(`failed to read input file: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  let spec;
  try {
    spec = JSON.parse(text);
  } catch (err) {
    process.stderr.write(`invalid JSON: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  let plan;
  try {
    plan = planJobs(spec);
  } catch (err) {
    process.stderr.write(`${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  process.stdout.write(`${JSON.stringify(plan)}\n`);
}

const isMain = process.argv[1] && import.meta.url === `file://${process.argv[1]}`;
if (isMain) {
  main();
}

